//! The C emitter: analysed 68000 code as C for clang.
//!
//! [`emit`] turns every analysed function into one C function (Architecture Decisions 2 and
//! 3): blocks are goto labels, jumps into other functions are guaranteed tail calls, calls
//! are native calls whose returned 68000 address is checked against the expected return
//! address, and everything the analysis could not resolve goes through the runtime's
//! dispatcher. Each instruction is emitted from its IR with dead flag computations pruned.
//!
//! The output is a set of files: `ag_state.h` (generated by the abi crate), `ag_runtime.h`
//! (inline memory fast path and IR primitives), `ag_functions.h` (prototypes), `ag_NNN.c`
//! (whole functions in ROM order, cut at a line budget) and `ag_table.c` (the address table
//! the dispatcher searches: every function entry and resume point).

mod function;
mod printer;
mod program;

use std::collections::BTreeMap;
use std::io;
use std::path::Path;

use anygenesis_analysis::{Analysis, FlagLiveness};
use anygenesis_shared::Address;

/// Where interrupt check points go: `AG_CHECK` at the start of the chosen blocks, which
/// calls the runtime's `ag_check` once the cycle budget is spent (policy: M3.2).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
#[non_exhaustive]
pub enum CheckPoints {
    #[default]
    None,
    /// Every block start.
    BlockStarts,
    /// Every block a jump from the same or a later block of the function reaches: the
    /// targets of loop back-edges.
    LoopTargets,
}

/// The listing lines `#line` directives point at.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LineMap {
    /// The listing's file name as the directive spells it.
    pub file: String,
    /// The 1-based line of each instruction.
    pub lines: BTreeMap<Address, u32>,
}

/// Choices the emitter leaves to its caller.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmitOptions {
    /// Charges each instruction's cycle estimate through `AG_CYCLES`.
    pub cycles: bool,
    pub check_points: CheckPoints,
    /// Adds a `#line` directive before every instruction found in the map.
    pub lines: Option<LineMap>,
    /// Starts a new `.c` file once the current one has at least this many lines.
    pub chunk_lines: usize,
    /// Prepended to every global symbol the output defines (functions, `ag_table`,
    /// `ag_table_size`) and to the `ag_functions.h` include guard, so several outputs can
    /// link into one program. The `ag_*` externs keep their names.
    pub symbol_prefix: String,
}

impl Default for EmitOptions {
    fn default() -> Self {
        Self {
            cycles: false,
            check_points: CheckPoints::None,
            lines: None,
            chunk_lines: 20_000,
            symbol_prefix: String::new(),
        }
    }
}

/// One emitted file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OutputFile {
    pub name: String,
    pub text: String,
}

/// Everything [`emit`] produced, in a fixed order: headers, function files, the table.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Output {
    pub files: Vec<OutputFile>,
}

impl Output {
    /// Writes every file into `directory`, creating it if needed.
    ///
    /// # Errors
    /// Returns the first error creating the directory or writing a file.
    pub fn write_to(&self, directory: &Path) -> io::Result<()> {
        std::fs::create_dir_all(directory)?;
        for file in &self.files {
            std::fs::write(directory.join(&file.name), &file.text)?;
        }
        Ok(())
    }

    /// Returns the `.c` files, the ones a build compiles.
    pub fn sources(&self) -> impl Iterator<Item = &OutputFile> {
        self.files.iter().filter(|file| file.name.ends_with(".c"))
    }
}

/// Emits C for every function of `analysis`, with flags pruned by `liveness` (built from the
/// same analysis).
pub fn emit(analysis: &Analysis, liveness: &FlagLiveness<'_>, options: &EmitOptions) -> Output {
    program::emit(analysis, liveness, options)
}
